fn render_workflow_mermaid(
    workflow: &crate::SessionWorkflowGraph,
    resolutions: &[crate::SessionWorkflowNodeResolution],
    diagnostics: &[crate::SessionWorkflowDiagnostic],
) -> String {

    for diag in diagnostics {
        let diag_id = format!("diag_{}", mermaid_node_id(&diag.node_id));
        lines.push(format!(
            "  {}((\"{}\"))",
            diag_id,
            escape_mermaid_label(&format!("{}: {}", diag.code, diag.message))
        ));
        lines.push(format!(
            "  {} -.-> {}",
            diag_id,
            mermaid_node_id(&diag.node_id)
        ));
    }

    lines.join("\n")
}

